import{_ as a,o as t,c as o,a7 as i}from"./chunks/framework.FWlv_suP.js";const u=JSON.parse('{"title":"Click2Chat Privacy Policy","description":"Official Privacy Policy for Click2Chat.","frontmatter":{"title":"Click2Chat Privacy Policy","description":"Official Privacy Policy for Click2Chat.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"privacy/click2chat.md","filePath":"privacy/click2chat.md"}'),n={name:"privacy/click2chat.md"};function s(r,e,c,l,d,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="privacy-policy-for-click2chat" tabindex="-1">Privacy Policy for Click2Chat <a class="header-anchor" href="#privacy-policy-for-click2chat" aria-label="Permalink to &quot;Privacy Policy for Click2Chat&quot;">​</a></h1><p><strong>Effective Date:</strong> August 17, 2026<br><strong>Last Updated:</strong> August 22, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Click2Chat is a lightweight utility developed by <strong>Anand Raja</strong>. It lets you start a WhatsApp or WhatsApp Business conversation by entering a country code and phone number, without first saving that number as a contact.</p><p>Click2Chat does not require an account and does not include advertising, analytics, tracking, or developer-operated cloud storage.</p><h2 id="numbers-country-selection-and-messages" tabindex="-1">Numbers, Country Selection, and Messages <a class="header-anchor" href="#numbers-country-selection-and-messages" aria-label="Permalink to &quot;Numbers, Country Selection, and Messages&quot;">​</a></h2><p>The phone number and optional message you enter are held temporarily while you prepare a chat. Click2Chat formats this information locally and does not save the number or message as an app record.</p><p>India is selected on first launch. The country and calling code remain synchronized when you edit either one. Your last selected country and your light, dark, or system theme preference can be stored locally on your device so they can be restored later. These preferences are not sent to the developer.</p><h2 id="clipboard-access" tabindex="-1">Clipboard Access <a class="header-anchor" href="#clipboard-access" aria-label="Permalink to &quot;Clipboard Access&quot;">​</a></h2><p>Click2Chat reads clipboard text only when you press the paste button. It does not monitor the clipboard in the background. Pasted text is placed into the phone-number field and is handled like text you enter manually.</p><h2 id="whatsapp-and-external-services" tabindex="-1">WhatsApp and External Services <a class="header-anchor" href="#whatsapp-and-external-services" aria-label="Permalink to &quot;WhatsApp and External Services&quot;">​</a></h2><p>When you choose to open a chat, Click2Chat passes the formatted phone number and optional message to WhatsApp, WhatsApp Business, or the <code>wa.me</code> web service. If both Android applications are installed, Click2Chat lets you choose one. If only one is installed, the app can open it directly.</p><p>The selected service receives the number and message needed to perform the action you requested. Its own privacy policy and terms apply. Click2Chat does not send a message automatically.</p><p>On Android, Click2Chat checks locally whether the WhatsApp and WhatsApp Business package names are available. This installed-app check is not transmitted to the developer.</p><h2 id="permissions-and-device-access" tabindex="-1">Permissions and Device Access <a class="header-anchor" href="#permissions-and-device-access" aria-label="Permalink to &quot;Permissions and Device Access&quot;">​</a></h2><p>The Play Store build does not request access to SMS, contacts, the microphone, location, camera, or device files. It does not request permission to place phone calls.</p><h2 id="network-and-hosting" tabindex="-1">Network and Hosting <a class="header-anchor" href="#network-and-hosting" aria-label="Permalink to &quot;Network and Hosting&quot;">​</a></h2><p>The browser version can be hosted as a static website. The hosting provider may process ordinary technical request information, such as an IP address, browser type, and request time, under its own policies. Click2Chat itself does not add analytics or tracking.</p><p>Opening a chat creates a user-initiated connection to WhatsApp or <code>wa.me</code>. Apart from loading the static application and actions you initiate, Click2Chat does not transmit phone numbers, messages, clipboard text, or preferences to a developer-operated service.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and Deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and Deletion&quot;">​</a></h2><p>Typed numbers, pasted text, and draft messages are not persisted by Click2Chat. They leave app memory when the app session ends.</p><p>To remove the saved country and theme preferences, clear Click2Chat storage in Android system settings, uninstall the Android app, or clear the site&#39;s storage in your browser.</p><p>Because Click2Chat has no account or developer database, the developer does not hold app records that can be deleted through an email request.</p><h2 id="children-s-privacy" tabindex="-1">Children&#39;s Privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to &quot;Children&#39;s Privacy&quot;">​</a></h2><p>Click2Chat is a general utility and is not directed to children. The developer does not knowingly collect personal information from children through the app.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to This Policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to This Policy&quot;">​</a></h2><p>This policy may be updated when Click2Chat&#39;s features or data practices change. The dates above will be revised when an update is published.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',29)])])}const m=a(n,[["render",s]]);export{u as __pageData,m as default};
